        MemoryPair(id: 't10', term: 'Fiscal Year', match: 'السنة المالية'),
        MemoryPair(id: 't11', term: 'Appropriation', match: 'الاعتماد'),
        MemoryPair(id: 't12', term: 'Virement', match: 'المناقلة'),
        MemoryPair(id: 't13', term: 'MTEF', match: 'إطار الإنفاق متوسط المدى'),
        MemoryPair(id: 't14', term: 'Line-Item Budget', match: 'موازنة البنود'),
        MemoryPair(id: 't15', term: 'Performance Budget', match: 'موازنة الأداء'),
        MemoryPair(id: 't16', term: 'Encumbrance', match: 'الارتباط'),
        MemoryPair(id: 't17', term: 'Budget Ceiling', match: 'سقف الموازنة'),
        MemoryPair(id: 't18', term: 'Commitment Control', match: 'الرقابة على الالتزامات'),
        MemoryPair(id: 't19', term: 'PPBS', match: 'نظام التخطيط والبرمجة والموازنة'),
        MemoryPair(id: 't20', term: 'Supreme Audit Institution', match: 'الجهاز الأعلى للرقابة المالية'),
