    ModuleActivity(
      id: 'budgetCycleSequencer',
      tab: ActivityTab.games,
      kind: ActivityKind.ordering,
      title: Bi('Budget Process Sequencer', 'مرتب مراحل عملية الموازنة'),
      description: Bi('Arrange budget cycle phases', 'رتب مراحل دورة الموازنة'),
      maxScore: 50,
      instruction: Bi('Arrange the six stages of the government budget process in the correct order.', 'رتب مراحل عملية الموازنة الحكومية الست بالترتيب الصحيح.'),
      steps: [
        OrderStep(id: 'phase1', name: Bi('Macro-Fiscal Framework', 'الإطار المالي الكلي'), description: Bi('Establish economic assumptions, revenue projections, and aggregate expenditure ceilings that guide the entire budget.', 'وضع الافتراضات الاقتصادية وتوقعات الإيرادات وسقوف الإنفاق الإجمالية التي توجه الموازنة بأكملها.'), hint: Bi('Before any ministry can plan, the government must set the overall economic context and spending limits.', 'قبل أن تتمكن أي وزارة من التخطيط، يجب على الحكومة تحديد السياق الاقتصادي العام وحدود الإنفاق.')),
        OrderStep(id: 'phase2', name: Bi('Budget Preparation', 'إعداد الموازنة'), description: Bi('Ministries prepare detailed budget requests within ceilings, followed by hearings and consolidation into a unified budget proposal.', 'تعد الوزارات طلبات موازنة تفصيلية ضمن السقوف المحددة، تليها جلسات استماع ودمج في مقترح موازنة موحد.'), hint: Bi('After the fiscal framework is set, individual ministries develop their spending plans within the assigned ceilings.', 'بعد تحديد الإطار المالي، تطور كل وزارة خطط إنفاقها ضمن السقوف المخصصة لها.')),
        OrderStep(id: 'phase3', name: Bi('Legislative Approval', 'الموافقة التشريعية'), description: Bi('The consolidated budget is submitted to the legislature for debate, amendment, and formal appropriation.', 'تقدم الموازنة الموحدة إلى السلطة التشريعية للمناقشة والتعديل واعتماد الاعتمادات المالية رسمياً.'), hint: Bi('The prepared budget must be legally authorized before any funds can be spent.', 'يجب أن تحصل الموازنة المعدة على تفويض قانوني قبل إنفاق أي أموال.')),
        OrderStep(id: 'phase4', name: Bi('Execution', 'التنفيذ'), description: Bi('Funds are released to ministries and spending occurs according to the approved appropriations and procurement rules.', 'يفرج عن الأموال للوزارات ويتم الإنفاق وفقاً للاعتمادات المعتمدة وقواعد المشتريات.'), hint: Bi('Once the legislature approves, the government puts the budget into action.', 'بمجرد موافقة السلطة التشريعية، تضع الحكومة الموازنة موضع التنفيذ.')),
        OrderStep(id: 'phase5', name: Bi('Monitoring & Reporting', 'المتابعة وإعداد التقارير'), description: Bi('Track actual spending against budgeted amounts, produce periodic fiscal reports, and flag variances for corrective action.', 'تتبع الإنفاق الفعلي مقابل المبالغ المدرجة في الموازنة، وإعداد تقارير مالية دورية، ورصد الانحرافات لاتخاذ إجراءات تصحيحية.'), hint: Bi('During execution, progress must be tracked and reported to ensure the budget stays on course.', 'أثناء التنفيذ، يجب تتبع التقدم والإبلاغ عنه لضمان بقاء الموازنة على المسار الصحيح.')),
        OrderStep(id: 'phase6', name: Bi('Audit & Evaluation', 'التدقيق والتقييم'), description: Bi('Independent auditors review financial compliance, value for money, and program outcomes; findings feed into the next budget cycle.', 'يراجع المدققون المستقلون الامتثال المالي والقيمة مقابل المال ونتائج البرامج، وتغذي النتائج دورة الموازنة التالية.'), hint: Bi('The final stage: an independent review of whether public money was spent properly and effectively.', 'المرحلة الأخيرة - مراجعة مستقلة لما إذا كان المال العام قد أنفق بشكل سليم وفعال.')),
      ],
    ),
    ModuleActivity(
      id: 'budgetSimulator',
      tab: ActivityTab.sim,
      kind: ActivityKind.caseScenario,
      title: Bi('Budget Meeting Simulator', 'محاكي اجتماع الموازنة'),
      description: Bi('Make decisions in budget scenarios', 'اتخذ قرارات في سيناريوهات الموازنة'),
      maxScore: 100,
      instruction: Bi('Navigate real-world budget scenarios from both private and government sectors. Analyze data, make decisions, and present recommendations to stakeholders.', 'تعامل مع سيناريوهات موازنة واقعية من القطاعين الخاص والحكومي. حلل البيانات، واتخذ القرارات، واعرض التوصيات على أصحاب المصلحة.'),
      scenarios: [
        CaseScenario(id: 'scenario1', title: Bi('Annual Budget Committee Meeting', 'اجتماع لجنة الموازنة السنوية'), role: Bi('Finance Manager, NexGen Manufacturing', 'مدير مالي، شركة NexGen للتصنيع'), overview: Bi('NexGen Manufacturing is building next year\'s master budget. The sales team projects 15% revenue growth, but the operations director is concerned that current production capacity cannot support that volume without significant capital investment.', 'تعمل شركة NexGen للتصنيع على بناء الموازنة الرئيسية للعام المقبل. ويتوقع فريق المبيعات نمواً في الإيرادات بنسبة 15%، لكن مدير العمليات يخشى أن الطاقة الإنتاجية الحالية لا يمكنها دعم هذا الحجم دون استثمار رأسمالي كبير.'), finalSummary: Bi('You successfully guided the budget committee through a realistic private-sector budgeting challenge: identifying a capacity constraint, selecting a flexible forecasting methodology, recommending a capital investment, and framing the proposal for board approval.', 'لقد قدت لجنة الموازنة بنجاح عبر تحدٍ واقعي لإعداد الموازنة في القطاع الخاص - تحديد قيد في الطاقة، واختيار منهجية تنبؤ مرنة، والتوصية باستثمار رأسمالي، وصياغة المقترح للحصول على موافقة المجلس.'), steps: [
            CaseStep(id: 'step1', type: CaseStepType.analysis, title: Bi('Review Sales Forecast', 'مراجعة توقعات المبيعات'), description: Bi('The sales department has submitted a forecast projecting 15% year-over-year growth. You need to evaluate the assumptions behind the projection.', 'قدم قسم المبيعات توقعات تتنبأ بنمو سنوي بنسبة 15%. وعليك تقييم الافتراضات التي يستند إليها هذا التوقع.'), data: [CaseDatum(Bi('Current Year Revenue', 'إيرادات العام الحالي'), '\$20M'), CaseDatum(Bi('Projected Revenue (Next Year)', 'الإيرادات المتوقعة (العام المقبل)'), '\$23M (+15%)'), CaseDatum(Bi('Current Plant Capacity', 'الطاقة الحالية للمصنع'), '85% utilized'), CaseDatum(Bi('Max Output at Current Capacity', 'أقصى إنتاج بالطاقة الحالية'), '\$21.5M equivalent')], question: Bi('What is the key risk in the sales forecast?', 'ما الخطر الرئيسي في توقعات المبيعات؟'), options: [
                CaseOption(Bi('Production capacity cannot support the projected volume', 'الطاقة الإنتاجية لا يمكنها دعم الحجم المتوقع'), isCorrect: true, feedback: Bi('Correct! Current capacity maxes out at roughly \$21.5M in revenue-equivalent output. The \$23M target creates a \$1.5M gap that cannot be filled without expanding capacity.', 'صحيح! تبلغ الطاقة الحالية حدها الأقصى عند نحو \$21.5M من الإنتاج المكافئ للإيرادات. ويخلق هدف \$23M فجوة قدرها \$1.5M لا يمكن سدها دون توسيع الطاقة.')),
                CaseOption(Bi('The marketing budget is insufficient', 'موازنة التسويق غير كافية'), feedback: Bi('Marketing spend was not flagged as a concern. The data points to a physical capacity constraint, not a demand-generation issue.', 'لم يشر إلى الإنفاق التسويقي كمصدر قلق. وتشير البيانات إلى قيد في الطاقة المادية، لا إلى مشكلة في توليد الطلب.')),
                CaseOption(Bi('The pricing strategy needs revision', 'استراتيجية التسعير بحاجة إلى مراجعة'), feedback: Bi('There is no indication of pricing pressure in the data. The mismatch is between projected volume and available production capacity.', 'لا يوجد في البيانات ما يشير إلى ضغط في التسعير. فالتعارض قائم بين الحجم المتوقع والطاقة الإنتاجية المتاحة.')),
            ]),
            CaseStep(id: 'step2', type: CaseStepType.decision, title: Bi('Choose Budgeting Approach', 'اختيار منهجية إعداد الموازنة'), description: Bi('Given the uncertainty around whether the capacity gap can be closed in time, you must recommend the most appropriate budgeting methodology for next year.', 'نظراً لعدم اليقين بشأن إمكانية سد فجوة الطاقة في الوقت المناسب، عليك التوصية بأنسب منهجية لإعداد الموازنة للعام المقبل.'), context: Bi('The company has historically used a static annual budget. However, with a major capacity investment under consideration, actual results could diverge significantly from the original plan.', 'اعتمدت الشركة تاريخياً على موازنة سنوية ثابتة. غير أنه مع وجود استثمار كبير في الطاقة قيد الدراسة، قد تنحرف النتائج الفعلية انحرافاً كبيراً عن الخطة الأصلية.'), question: Bi('Which budgeting approach best handles this uncertainty?', 'أي منهجية لإعداد الموازنة تتعامل مع عدم اليقين هذا على أفضل وجه؟'), options: [
                CaseOption(Bi('Static annual budget (traditional approach)', 'موازنة سنوية ثابتة (المنهج التقليدي)'), feedback: Bi('A static budget locks in assumptions at the start of the year. If the capacity expansion is delayed or accelerated, the budget quickly becomes irrelevant.', 'تثبت الموازنة الثابتة الافتراضات في بداية العام. وإذا تأخر توسيع الطاقة أو تسارع، تفقد الموازنة جدواها بسرعة.')),
                CaseOption(Bi('Rolling forecast with quarterly updates', 'تنبؤ متجدد مع تحديثات ربع سنوية'), isCorrect: true, feedback: Bi('Correct! A rolling forecast lets you update revenue and cost assumptions each quarter as the capacity project progresses. This keeps the budget aligned with reality.', 'صحيح! يتيح لك التنبؤ المتجدد تحديث افتراضات الإيرادات والتكاليف كل ربع سنة مع تقدم مشروع الطاقة. وهذا يبقي الموازنة متسقة مع الواقع.')),
                CaseOption(Bi('Zero-based budget', 'الموازنة الصفرية'), feedback: Bi('Zero-based budgeting is useful for cost optimization but does not specifically address the timing uncertainty of a major capacity investment.', 'الموازنة الصفرية مفيدة لتحسين التكاليف، لكنها لا تعالج تحديداً عدم اليقين المتعلق بتوقيت استثمار كبير في الطاقة.')),
            ]),
            CaseStep(id: 'step3', type: CaseStepType.recommendation, title: Bi('Address the Capacity Gap', 'معالجة فجوة الطاقة'), description: Bi('The committee agrees that a capacity solution is needed. You must recommend the best way to close the gap and support the growth target.', 'تتفق اللجنة على الحاجة إلى حل يخص الطاقة. وعليك التوصية بأفضل طريقة لسد الفجوة ودعم هدف النمو.'), question: Bi('How should the company address the capacity constraint?', 'كيف ينبغي أن تعالج الشركة قيد الطاقة؟'), options: [
                CaseOption(Bi('Reject the sales target and cap revenue at current capacity', 'رفض هدف المبيعات وتقييد الإيرادات عند الطاقة الحالية'), feedback: Bi('Capping growth forfeits market opportunity and may lead to competitors capturing the demand the company could have served.', 'يؤدي تقييد النمو إلى التخلي عن فرصة سوقية، وقد يدفع المنافسين إلى الاستحواذ على الطلب الذي كان بإمكان الشركة تلبيته.'), consequence: Bi('Competitors gain market share while the company stagnates.', 'يكتسب المنافسون حصة سوقية بينما تراوح الشركة مكانها.')),
                CaseOption(Bi('Approve CapEx for new equipment to expand capacity', 'اعتماد نفقات رأسمالية لمعدات جديدة لتوسيع الطاقة'), isCorrect: true, feedback: Bi('Correct! Investing in new equipment directly addresses the bottleneck. Combined with the rolling forecast, the company can track ROI and adjust as installation progresses.', 'صحيح! يعالج الاستثمار في معدات جديدة عنق الزجاجة بشكل مباشر. وإلى جانب التنبؤ المتجدد، يمكن للشركة تتبع العائد على الاستثمار والتعديل مع تقدم التركيب.'), consequence: Bi('Capacity expands to support the growth plan, with clear ROI tracking via the rolling forecast.', 'تتوسع الطاقة لدعم خطة النمو، مع تتبع واضح للعائد على الاستثمار عبر التنبؤ المتجدد.')),
                CaseOption(Bi('Outsource excess production to a contract manufacturer', 'إسناد الإنتاج الزائد إلى مصنع متعاقد من الخارج'), feedback: Bi('Outsourcing can work short-term, but higher per-unit costs and quality control risks make it a poor long-term strategy for a 15% sustained growth plan.', 'قد ينجح الإسناد الخارجي على المدى القصير، لكن ارتفاع تكلفة الوحدة ومخاطر ضبط الجودة يجعلانه استراتيجية ضعيفة على المدى الطويل لخطة نمو مستدام بنسبة 15%.'), consequence: Bi('Margins erode and quality issues may damage brand reputation.', 'تتآكل الهوامش وقد تضر مشكلات الجودة بسمعة العلامة التجارية.')),
            ]),
            CaseStep(id: 'step4', type: CaseStepType.stakeholder, title: Bi('Present to the Board', 'العرض على مجلس الإدارة'), description: Bi('You are presenting the final budget recommendation to the Board of Directors. Your framing will determine whether the proposal gains approval.', 'أنت تعرض توصية الموازنة النهائية على مجلس الإدارة. وستحدد طريقة عرضك ما إذا كان المقترح سيحظى بالموافقة.'), question: Bi('How should you frame the budget recommendation to the board?', 'كيف ينبغي أن تصوغ توصية الموازنة أمام المجلس؟'), options: [
                CaseOption(Bi('Focus only on the growth opportunity and revenue upside', 'التركيز فقط على فرصة النمو والمكاسب المحتملة في الإيرادات'), feedback: Bi('An unbalanced pitch that ignores execution risk will not inspire board confidence. Directors need to see that risks have been considered.', 'العرض غير المتوازن الذي يتجاهل مخاطر التنفيذ لن يبعث الثقة في المجلس. فأعضاء المجلس بحاجة إلى أن يروا أن المخاطر قد أخذت في الاعتبار.')),
                CaseOption(Bi('Focus only on risks and the need for caution', 'التركيز فقط على المخاطر والحاجة إلى الحذر'), feedback: Bi('A purely cautionary tone may cause the board to shelve the investment entirely, missing a genuine growth opportunity.', 'قد تدفع النبرة الحذرة بحتة المجلس إلى تأجيل الاستثمار كلياً، وبذلك تضيع فرصة نمو حقيقية.')),
                CaseOption(Bi('Balance the growth opportunity with the capacity investment plan and risk mitigation', 'الموازنة بين فرصة النمو وخطة الاستثمار في الطاقة والتخفيف من المخاطر'), isCorrect: true, feedback: Bi('Correct! A balanced presentation shows you have identified the opportunity, quantified the required investment, and built in quarterly checkpoints through the rolling forecast.', 'صحيح! يظهر العرض المتوازن أنك حددت الفرصة، وقدرت الاستثمار المطلوب، وبنيت نقاط مراجعة ربع سنوية من خلال التنبؤ المتجدد.')),
            ]),
          ]),
        CaseScenario(id: 'scenario2', title: Bi('Mid-Year Supplementary Budget', 'الموازنة الإضافية في منتصف العام'), role: Bi('Senior Budget Officer, Ministry of Finance', 'مسؤول موازنة أول، وزارة المالية'), overview: Bi('Six months into the fiscal year, the Ministry of Education has submitted a request for AED 40 million in supplementary funding to construct new schools mandated by a recent cabinet directive. You must assess the request, identify the best funding source, and determine the correct approval process.', 'بعد مرور ستة أشهر من السنة المالية، قدمت وزارة التعليم طلباً بتمويل إضافي قدره AED 40 مليون لبناء مدارس جديدة بموجب توجيه حكومي حديث لمجلس الوزراء. وعليك تقييم الطلب، وتحديد أفضل مصدر للتمويل، وتحديد عملية الموافقة الصحيحة.'), finalSummary: Bi('You successfully navigated a government supplementary budget process: assessing the legitimacy of the request, selecting the appropriate funding source from contingency reserves, and recommending the correct Cabinet-level approval pathway with legislative notification.', 'لقد أدرت بنجاح عملية موازنة حكومية إضافية - تقييم مشروعية الطلب، واختيار مصدر التمويل المناسب من الاحتياطيات الطارئة، والتوصية بمسار الموافقة الصحيح على مستوى مجلس الوزراء مع إخطار السلطة التشريعية.'), steps: [
            CaseStep(id: 'step1', type: CaseStepType.analysis, title: Bi('Assess the Supplementary Request', 'تقييم الطلب الإضافي'), description: Bi('Review the Ministry of Education\'s spending track record and the details of the supplementary request.', 'راجع سجل إنفاق وزارة التعليم وتفاصيل الطلب الإضافي.'), data: [CaseDatum(Bi('Original Annual Budget', 'الموازنة السنوية الأصلية'), 'AED 250M'), CaseDatum(Bi('Spent to Date (6 months)', 'المنفق حتى تاريخه (6 أشهر)'), 'AED 118M'), CaseDatum(Bi('Supplementary Request', 'الطلب الإضافي'), 'AED 40M'), CaseDatum(Bi('Reason', 'السبب'), 'New school construction (cabinet mandate)')], question: Bi('What is your initial assessment of this request?', 'ما تقييمك المبدئي لهذا الطلب؟'), options: [
                CaseOption(Bi('Reasonable - the ministry is on track with current spending and the need is driven by a legitimate cabinet mandate', 'معقول - الوزارة منضبطة في إنفاقها الحالي والحاجة ناشئة عن تكليف حكومي مشروع'), isCorrect: true, feedback: Bi('Correct! With AED 118M spent at mid-year against a AED 250M budget (47.2%), spending is well controlled. The supplementary request stems from a new mandate that could not have been foreseen during original budget preparation.', 'صحيح! مع إنفاق AED 118M في منتصف العام مقابل موازنة قدرها AED 250M (47.2%)، فإن الإنفاق مضبوط بشكل جيد. وينبع الطلب الإضافي من تكليف جديد لم يكن بالإمكان توقعه أثناء إعداد الموازنة الأصلية.')),
                CaseOption(Bi('Reject - the construction should have been included in the original budget', 'الرفض - كان ينبغي إدراج البناء في الموازنة الأصلية'), feedback: Bi('The cabinet directive was issued after the original budget was approved. Supplementary budgets exist precisely for legitimate new mandates that arise mid-year.', 'صدر توجيه مجلس الوزراء بعد اعتماد الموازنة الأصلية. والموازنات الإضافية موجودة تحديداً للتكليفات الجديدة المشروعة التي تنشأ في منتصف العام.')),
                CaseOption(Bi('Suspicious - the ministry may be padding its budget', 'مريب - قد تكون الوزارة تضخم موازنتها'), feedback: Bi('The ministry\'s spending rate (47.2% at mid-year) is disciplined, and the request is backed by an official cabinet directive. There is no evidence of budget padding.', 'معدل إنفاق الوزارة (47.2% في منتصف العام) منضبط، والطلب مدعوم بتوجيه رسمي من مجلس الوزراء. ولا يوجد دليل على تضخيم الموازنة.')),
            ]),
            CaseStep(id: 'step2', type: CaseStepType.decision, title: Bi('Identify Funding Source', 'تحديد مصدر التمويل'), description: Bi('The request is deemed valid. You now need to recommend the most appropriate source of funds for the AED 40M supplementary budget.', 'يعد الطلب صحيحاً. وعليك الآن التوصية بأنسب مصدر للأموال للموازنة الإضافية البالغة AED 40M.'), context: Bi('Government fiscal rules require that every supplementary budget identify a clear funding source: contingency reserves, reallocation from underspending ministries, or new borrowing.', 'تقتضي القواعد المالية الحكومية أن تحدد كل موازنة إضافية مصدر تمويل واضحاً - الاحتياطيات الطارئة، أو إعادة التخصيص من وزارات لم تستنفد إنفاقها، أو اقتراض جديد.'), question: Bi('What is the most appropriate funding source?', 'ما مصدر التمويل الأنسب؟'), options: [
                CaseOption(Bi('Contingency reserve (currently holds AED 80M)', 'الاحتياطي الطارئ (يبلغ حالياً AED 80M)'), isCorrect: true, feedback: Bi('Correct! Contingency reserves are specifically designed for unforeseen, legitimate expenditures. Drawing AED 40M from an AED 80M reserve is prudent and preserves a buffer for the remainder of the year.', 'صحيح! الاحتياطيات الطارئة مصممة تحديداً للنفقات المشروعة غير المتوقعة. وسحب AED 40M من احتياطي قدره AED 80M إجراء حصيف يبقي هامشاً وقائياً لبقية العام.')),
                CaseOption(Bi('Reallocate from the Ministry of Health budget', 'إعادة التخصيص من موازنة وزارة الصحة'), feedback: Bi('Cross-ministry reallocation requires lengthy legislative procedures and risks disrupting health programs. It should only be considered when contingency reserves are exhausted.', 'تتطلب إعادة التخصيص بين الوزارات إجراءات تشريعية مطولة وتنطوي على خطر تعطيل البرامج الصحية. ولا ينبغي النظر فيها إلا عند استنفاد الاحتياطيات الطارئة.')),
